@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService Equipment
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private const string PersistenceKey = "inventory-items";
    private IReadOnlyList<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe so that during SSR prerender, the runtime calls our
        // callback to persist the data into the HTML payload.
        _subscription = ApplicationState.RegisterOnPersisting(PersistState);

        // If persisted state exists (interactive reconnect), use it
        // instead of calling the service a second time.
        if (ApplicationState.TryTakeFromJson<IReadOnlyList<EquipmentItem>>(
                PersistenceKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            // First render (SSR) — actually fetch the data.
            _items = await Equipment.GetEquipmentAsync();
        }
    }

    private Task PersistState()
    {
        ApplicationState.PersistAsJson(PersistenceKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

